-- iOS Distribution Platform — initial schema (Cloudflare D1 / SQLite)
-- Conventions: ids are opaque UUIDs (TEXT); timestamps are ISO-8601 UTC strings
-- generated by the application (lexicographically sortable); JSON columns are TEXT.
-- Forward-fix guidance: never edit an applied migration; add 000N_*.sql instead.

PRAGMA foreign_keys = ON;

CREATE TABLE users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  display_name TEXT NOT NULL,
  password_hash TEXT,
  email_verified_at TEXT,
  avatar_r2_key TEXT,
  is_platform_owner INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','invited','disabled')),
  failed_login_count INTEGER NOT NULL DEFAULT 0,
  locked_until TEXT,
  last_login_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE organisations (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  logo_r2_key TEXT,
  timezone TEXT NOT NULL DEFAULT 'UTC',
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','archived')),
  default_link_expiry_days INTEGER NOT NULL DEFAULT 14,
  default_qa_instructions TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE organisation_members (
  id TEXT PRIMARY KEY,
  organisation_id TEXT NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('org_admin','project_admin','qa_manager','qa_tester','viewer')),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','invited','deactivated')),
  invited_by TEXT REFERENCES users(id),
  joined_at TEXT,
  created_at TEXT NOT NULL,
  UNIQUE (organisation_id, user_id)
);
CREATE INDEX idx_org_members_user ON organisation_members(user_id, status);

CREATE TABLE projects (
  id TEXT PRIMARY KEY,
  organisation_id TEXT NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  slug TEXT NOT NULL,
  description TEXT,
  app_display_name TEXT,
  expected_bundle_identifier TEXT,
  platform TEXT NOT NULL DEFAULT 'ios' CHECK (platform IN ('ios')),
  icon_r2_key TEXT,
  default_qa_instructions TEXT,
  default_install_instructions TEXT,
  access_policy TEXT NOT NULL DEFAULT 'named_users_only'
    CHECK (access_policy IN ('named_users_only','allow_protected_links')),
  feedback_enabled INTEGER NOT NULL DEFAULT 1,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','paused','archived')),
  created_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (organisation_id, slug)
);
CREATE INDEX idx_projects_org ON projects(organisation_id, status, updated_at);

CREATE TABLE project_members (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('project_admin','qa_manager','qa_tester','viewer')),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','removed')),
  added_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL,
  UNIQUE (project_id, user_id)
);
CREATE INDEX idx_project_members_user ON project_members(user_id, status);

CREATE TABLE upload_sessions (
  id TEXT PRIMARY KEY,
  organisation_id TEXT NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id),
  r2_object_key TEXT NOT NULL,
  multipart_upload_id TEXT,
  original_filename TEXT NOT NULL,
  expected_size_bytes INTEGER NOT NULL,
  expected_sha256 TEXT NOT NULL,
  part_size_bytes INTEGER NOT NULL,
  idempotency_key TEXT,
  build_id TEXT,
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','completing','completed','aborted','expired','failed')),
  failure_reason TEXT,
  expires_at TEXT NOT NULL,
  completed_at TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX idx_upload_sessions_status ON upload_sessions(status, expires_at);
CREATE UNIQUE INDEX idx_upload_sessions_idem ON upload_sessions(user_id, idempotency_key) WHERE idempotency_key IS NOT NULL;

CREATE TABLE upload_parts (
  upload_session_id TEXT NOT NULL REFERENCES upload_sessions(id) ON DELETE CASCADE,
  part_number INTEGER NOT NULL,
  etag TEXT NOT NULL,
  size_bytes INTEGER NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (upload_session_id, part_number)
);

CREATE TABLE builds (
  id TEXT PRIMARY KEY,
  organisation_id TEXT NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  uploaded_by TEXT REFERENCES users(id),
  original_filename TEXT NOT NULL,
  r2_object_key TEXT NOT NULL,
  file_size_bytes INTEGER NOT NULL,
  sha256 TEXT NOT NULL,
  app_name TEXT,
  bundle_identifier TEXT,
  version TEXT,
  build_number TEXT,
  minimum_os_version TEXT,
  supported_device_families_json TEXT,
  architectures_json TEXT,
  release_title TEXT,
  release_notes TEXT,
  internal_notes TEXT,
  declared_version TEXT,
  declared_build_number TEXT,
  distribution_method TEXT NOT NULL DEFAULT 'determine_from_ipa'
    CHECK (distribution_method IN ('determine_from_ipa','ad_hoc','development','enterprise','testflight','app_store','download_only')),
  external_install_url TEXT,
  validation_status TEXT NOT NULL DEFAULT 'pending'
    CHECK (validation_status IN ('pending','running','completed','failed')),
  eligibility_status TEXT NOT NULL DEFAULT 'needs_review'
    CHECK (eligibility_status IN ('eligible','eligible_with_warnings','not_eligible','needs_review')),
  processing_status TEXT NOT NULL DEFAULT 'upload_received',
  allow_download_when_ineligible INTEGER NOT NULL DEFAULT 0,
  publish_status TEXT NOT NULL DEFAULT 'unpublished' CHECK (publish_status IN ('unpublished','published','archived')),
  uploaded_at TEXT NOT NULL,
  validated_at TEXT,
  published_at TEXT,
  archived_at TEXT,
  deleted_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX idx_builds_project ON builds(project_id, deleted_at, created_at);
CREATE INDEX idx_builds_org ON builds(organisation_id, created_at);
CREATE INDEX idx_builds_status ON builds(validation_status, eligibility_status, publish_status);
CREATE INDEX idx_builds_bundle ON builds(bundle_identifier);

CREATE TABLE build_files (
  id TEXT PRIMARY KEY,
  build_id TEXT NOT NULL REFERENCES builds(id) ON DELETE CASCADE,
  file_type TEXT NOT NULL CHECK (file_type IN ('ipa','manifest','validation_report','icon','other')),
  r2_object_key TEXT NOT NULL,
  mime_type TEXT NOT NULL,
  size_bytes INTEGER NOT NULL,
  sha256 TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX idx_build_files_build ON build_files(build_id, file_type);

CREATE TABLE worker_registry (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  platform TEXT NOT NULL DEFAULT 'macos',
  token_hash TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','revoked')),
  worker_version TEXT,
  last_heartbeat_at TEXT,
  current_job_id TEXT,
  jobs_completed INTEGER NOT NULL DEFAULT 0,
  jobs_failed INTEGER NOT NULL DEFAULT 0,
  last_error TEXT,
  created_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL,
  revoked_at TEXT
);

CREATE TABLE worker_jobs (
  id TEXT PRIMARY KEY,
  build_id TEXT NOT NULL REFERENCES builds(id) ON DELETE CASCADE,
  worker_id TEXT REFERENCES worker_registry(id),
  job_type TEXT NOT NULL DEFAULT 'validate_ipa',
  status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','claimed','running','completed','failed','cancelled')),
  attempt_count INTEGER NOT NULL DEFAULT 0,
  max_attempts INTEGER NOT NULL DEFAULT 3,
  progress_percent INTEGER NOT NULL DEFAULT 0,
  progress_message TEXT,
  stage TEXT,
  input_json TEXT,
  result_json TEXT,
  error_code TEXT,
  error_message TEXT,
  retryable INTEGER NOT NULL DEFAULT 1,
  lease_token_hash TEXT,
  lease_expires_at TEXT,
  idempotency_key TEXT UNIQUE,
  claimed_at TEXT,
  started_at TEXT,
  completed_at TEXT,
  next_attempt_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX idx_worker_jobs_claim ON worker_jobs(status, next_attempt_at);
CREATE INDEX idx_worker_jobs_build ON worker_jobs(build_id, created_at);
CREATE INDEX idx_worker_jobs_lease ON worker_jobs(status, lease_expires_at);

CREATE TABLE validation_reports (
  id TEXT PRIMARY KEY,
  build_id TEXT NOT NULL REFERENCES builds(id) ON DELETE CASCADE,
  worker_job_id TEXT NOT NULL REFERENCES worker_jobs(id),
  attempt INTEGER NOT NULL,
  worker_version TEXT,
  overall_status TEXT NOT NULL,
  eligibility_status TEXT NOT NULL,
  metadata_json TEXT,
  signing_summary_json TEXT,
  profile_summary_json TEXT,
  entitlements_summary_json TEXT,
  checks_json TEXT,
  warnings_json TEXT,
  errors_json TEXT,
  limitations_json TEXT,
  report_r2_key TEXT,
  started_at TEXT,
  completed_at TEXT,
  created_at TEXT NOT NULL,
  UNIQUE (worker_job_id, attempt)
);
CREATE INDEX idx_validation_reports_build ON validation_reports(build_id, created_at);

CREATE TABLE distribution_links (
  id TEXT PRIMARY KEY,
  organisation_id TEXT NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  build_id TEXT NOT NULL REFERENCES builds(id) ON DELETE CASCADE,
  created_by TEXT REFERENCES users(id),
  token_hash TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  access_scope TEXT NOT NULL CHECK (access_scope IN ('named_users','project_members','protected_link')),
  password_hash TEXT,
  expires_at TEXT,
  max_downloads INTEGER,
  download_count INTEGER NOT NULL DEFAULT 0,
  allow_download INTEGER NOT NULL DEFAULT 1,
  allow_feedback INTEGER NOT NULL DEFAULT 1,
  customer_release_notes TEXT,
  installation_guidance TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('draft','active','revoked')),
  created_at TEXT NOT NULL,
  revoked_at TEXT
);
CREATE INDEX idx_dist_links_build ON distribution_links(build_id, status);
CREATE INDEX idx_dist_links_project ON distribution_links(project_id, created_at);

CREATE TABLE distribution_link_members (
  id TEXT PRIMARY KEY,
  distribution_link_id TEXT NOT NULL REFERENCES distribution_links(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL,
  UNIQUE (distribution_link_id, user_id)
);

CREATE TABLE downloads (
  id TEXT PRIMARY KEY,
  distribution_link_id TEXT NOT NULL REFERENCES distribution_links(id) ON DELETE CASCADE,
  build_id TEXT NOT NULL REFERENCES builds(id) ON DELETE CASCADE,
  user_id TEXT REFERENCES users(id),
  event_type TEXT NOT NULL CHECK (event_type IN ('page_open','download_started','download_completed','manifest_requested','install_confirmed')),
  ip_hash TEXT,
  user_agent_summary TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX idx_downloads_link ON downloads(distribution_link_id, event_type, created_at);
CREATE INDEX idx_downloads_build ON downloads(build_id, created_at);

CREATE TABLE feedback (
  id TEXT PRIMARY KEY,
  organisation_id TEXT NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  build_id TEXT REFERENCES builds(id) ON DELETE SET NULL,
  reporter_user_id TEXT REFERENCES users(id),
  assigned_to_user_id TEXT REFERENCES users(id),
  category TEXT NOT NULL CHECK (category IN ('crash','ui_layout','performance','functional','installation','compatibility','other')),
  title TEXT NOT NULL,
  description TEXT NOT NULL,
  severity TEXT NOT NULL CHECK (severity IN ('critical','high','medium','low')),
  status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new','triaged','in_progress','need_more_info','resolved','closed')),
  device_model TEXT,
  ios_version TEXT,
  reproduction_steps TEXT,
  expected_result TEXT,
  actual_result TEXT,
  contact_preference TEXT NOT NULL DEFAULT 'in_app' CHECK (contact_preference IN ('in_app','email','none')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  resolved_at TEXT
);
CREATE INDEX idx_feedback_project ON feedback(project_id, status, created_at);
CREATE INDEX idx_feedback_reporter ON feedback(reporter_user_id, created_at);
CREATE INDEX idx_feedback_build ON feedback(build_id);

CREATE TABLE feedback_attachments (
  id TEXT PRIMARY KEY,
  feedback_id TEXT NOT NULL REFERENCES feedback(id) ON DELETE CASCADE,
  uploaded_by TEXT REFERENCES users(id),
  r2_object_key TEXT NOT NULL,
  original_filename TEXT NOT NULL,
  mime_type TEXT NOT NULL,
  size_bytes INTEGER NOT NULL,
  sha256 TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','ready','rejected')),
  created_at TEXT NOT NULL
);
CREATE INDEX idx_feedback_attachments_fb ON feedback_attachments(feedback_id);

CREATE TABLE feedback_comments (
  id TEXT PRIMARY KEY,
  feedback_id TEXT NOT NULL REFERENCES feedback(id) ON DELETE CASCADE,
  author_user_id TEXT REFERENCES users(id),
  body TEXT NOT NULL,
  visibility TEXT NOT NULL CHECK (visibility IN ('internal','customer')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX idx_feedback_comments_fb ON feedback_comments(feedback_id, created_at);

CREATE TABLE feedback_status_history (
  id TEXT PRIMARY KEY,
  feedback_id TEXT NOT NULL REFERENCES feedback(id) ON DELETE CASCADE,
  changed_by TEXT REFERENCES users(id),
  old_status TEXT,
  new_status TEXT NOT NULL,
  note TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX idx_feedback_history_fb ON feedback_status_history(feedback_id, created_at);

CREATE TABLE notifications (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  organisation_id TEXT REFERENCES organisations(id) ON DELETE CASCADE,
  type TEXT NOT NULL,
  title TEXT NOT NULL,
  body TEXT,
  resource_type TEXT,
  resource_id TEXT,
  email_state TEXT NOT NULL DEFAULT 'not_requested' CHECK (email_state IN ('not_requested','not_configured','queued','sent','failed')),
  read_at TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX idx_notifications_user ON notifications(user_id, read_at, created_at);

CREATE TABLE notification_preferences (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  event_type TEXT NOT NULL,
  in_app_enabled INTEGER NOT NULL DEFAULT 1,
  email_enabled INTEGER NOT NULL DEFAULT 1,
  updated_at TEXT NOT NULL,
  UNIQUE (user_id, event_type)
);

CREATE TABLE audit_logs (
  id TEXT PRIMARY KEY,
  organisation_id TEXT,
  actor_user_id TEXT,
  actor_type TEXT NOT NULL DEFAULT 'user' CHECK (actor_type IN ('user','worker','system','anonymous')),
  action TEXT NOT NULL,
  resource_type TEXT,
  resource_id TEXT,
  metadata_json TEXT,
  ip_hash TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX idx_audit_org ON audit_logs(organisation_id, created_at);
CREATE INDEX idx_audit_action ON audit_logs(action, created_at);
CREATE INDEX idx_audit_resource ON audit_logs(resource_type, resource_id);

CREATE TABLE login_sessions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  session_token_hash TEXT NOT NULL UNIQUE,
  csrf_token_hash TEXT,
  expires_at TEXT NOT NULL,
  last_seen_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  revoked_at TEXT
);
CREATE INDEX idx_sessions_user ON login_sessions(user_id, revoked_at);

CREATE TABLE invitations (
  id TEXT PRIMARY KEY,
  organisation_id TEXT NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,
  project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,
  project_ids_json TEXT,
  project_role TEXT,
  email TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('org_admin','project_admin','qa_manager','qa_tester','viewer')),
  token_hash TEXT NOT NULL UNIQUE,
  invited_by TEXT REFERENCES users(id),
  expires_at TEXT NOT NULL,
  accepted_at TEXT,
  revoked_at TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX idx_invitations_org ON invitations(organisation_id, email);

CREATE TABLE password_resets (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  used_at TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE platform_settings (
  key TEXT PRIMARY KEY,
  value_json TEXT NOT NULL,
  updated_by TEXT REFERENCES users(id),
  updated_at TEXT NOT NULL
);

CREATE TABLE rate_limits (
  bucket TEXT NOT NULL,
  window_start INTEGER NOT NULL,
  count INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (bucket, window_start)
);

CREATE TABLE email_outbox (
  id TEXT PRIMARY KEY,
  to_email TEXT NOT NULL,
  template TEXT NOT NULL,
  subject TEXT NOT NULL,
  body TEXT NOT NULL,
  notification_id TEXT,
  status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','sent','failed','not_configured')),
  attempts INTEGER NOT NULL DEFAULT 0,
  last_error TEXT,
  created_at TEXT NOT NULL,
  sent_at TEXT
);
CREATE INDEX idx_email_outbox_status ON email_outbox(status, created_at);
